#include <bits/stdc++.h>
using namespace std;

long long square(long long a) {
    return a * a;
}

long long distanceSquared(long long ax, long long ay, long long bx, long long by) {
    return square(ax - bx) + square(ay - by);
}

struct Point {
    vector<long long> coords;

    Point(const vector<long long>& c) : coords(c) {}

    long long lengthSquared() const {
        long long sum = 0;
        for (auto c : coords) {
            sum += c * c;
        }
        return sum;
    }

    long long dotProduct(const Point& other) const {
        long long result = 0;
        for (size_t i = 0; i < coords.size(); i++) {
            result += coords[i] * other.coords[i];
        }
        return result;
    }

    Point subtract(const Point& other) const {
        vector<long long> resultCoords(coords.size());
        for (size_t i = 0; i < coords.size(); i++) {
            resultCoords[i] = coords[i] - other.coords[i];
        }
        return Point(resultCoords);
    }
};

bool check(const vector<Point>& points, int index) {
    const Point& current = points[index];
    int n = points.size();
    for (int j = 0; j < n; j++) {
        if (j == index) continue;
        for (int k = 0; k < n; k++) {
            if (k == index || k == j) continue;
            Point x = points[j].subtract(current);
            Point y = points[k].subtract(current);
            if (x.dotProduct(y) > 0) return false;
        }
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n > 11) {
        cout << 0 << "\n";
        return 0;
    }
    vector<Point> points;
    for (int i = 0; i < n; i++) {
        vector<long long> coords(5);
        for (int j = 0; j < 5; j++) {
            cin >> coords[j];
        }
        points.emplace_back(coords);
    }
    vector<int> resultIndices;
    for (int i = 0; i < n; i++) {
        if (check(points, i)) {
            resultIndices.push_back(i + 1);
        }
    }
    cout << resultIndices.size() << "\n";
    for (int idx : resultIndices) {
        cout << idx << "\n";
    }
    return 0;
}
